/**
 * API RP 571 (3rd ed., 2020) damage mechanisms — the IRIS library, written in plain words for teaching,
 * with a screening rule per mechanism. A "yes" is a reason to look, not a finding — the engineer decides.
 * x (inputs): mat (CS LAS SS3 SS4 DSS NI CU AL TI CI), tmax, tmin and yes/no flags (see DM_Q).
 */
/* eslint-disable */
export type DmX = Record<string, any>;
export type DmAnswer = "yes" | "maybe" | "no" | "?";
export type DmScreen = { r: DmAnswer; why?: string; need?: string[] };
export type DmEntry = { id: string; api: string; n: string; g: string; mat: string[]; rbi: string; ffs: string; sw: string; why: string; who: string; look: string; find: string; stop: string; scr: (x: DmX) => DmScreen };

export const DM_MAT: Record<string, string> = { CS: 'Carbon steel', LAS: 'Low-alloy steel (Cr-Mo)', SS3: '300-series stainless', SS4: '400-series stainless', DSS: 'Duplex stainless', NI: 'Nickel alloy', CU: 'Copper alloy', AL: 'Aluminium', TI: 'Titanium', CI: 'Cast iron' };
export const DM_GRP: Record<string, string> = { mech: 'Mechanical and metallurgical', loss: 'Loss of thickness (uniform or local)', ht: 'High-temperature corrosion', eac: 'Environment-assisted cracking', ref: 'Process-specific (refining / petrochemical)' };
export const DM_RBI: Record<string, string> = { thin: 'Thinning', ext: 'External damage', scc: 'Stress corrosion cracking', htha: 'High-temperature hydrogen attack', brit: 'Brittle fracture / embrittlement', fat: 'Mechanical fatigue', creep: 'Creep (outside API 581 DFs)', none: '—' };
export const DM_FFS: Record<string, string> = { p4: 'API 579 Part 4 (general metal loss)', p5: 'Part 5 (local metal loss)', p6: 'Part 6 (pitting)', p7: 'Part 7 (HIC, blisters)', p9: 'Part 9 (crack-like flaws)', p10: 'Part 10 (creep)', p3: 'Part 3 (brittle fracture)', p11: 'Part 11 (fire damage)', p8: 'Part 8 (distortion)' };
/* small helpers for the rules: undefined = not known → the rule answers '?' and names the question */
const dmIs = (x: DmX, ...M: string[]): boolean | undefined => x.mat === undefined ? undefined : M.includes(x.mat);
const dmT = (x: DmX, a?: number | null, b?: number | null): boolean | undefined => x.tmax === undefined || x.tmax === null || isNaN(x.tmax) ? undefined : (a == null || x.tmax >= a) && (b == null || x.tmax <= b);
const dmF = (x: DmX, k: string): boolean | undefined => x[k] === undefined ? undefined : !!x[k];
/* combine conditions: all true → yes; any false → no; else ? with the unknown keys */
function dmAll(conds: [boolean | undefined, string][], why: string, yes: DmAnswer = 'yes'): DmScreen {
  const need = []; for (const [v, k] of conds) { if (v === false) return { r: 'no', why: '' }; if (v === undefined) need.push(k); }
  return need.length ? { r: '?', why, need } : { r: yes, why };
}
