/* the questions (one per input) — text written to be answered at the equipment */
export const DM_Q: Record<string, { t: string; type: "mat" | "num" | "yn" | "acid" }> = {
  mat: { t: 'Material of construction', type: 'mat' }, tmax: { t: 'Highest operating temperature (°C)', type: 'num' }, tmin: { t: 'Lowest metal temperature, including start-up, depressurising and hydrotest (°C)', type: 'num' },
  water: { t: 'Is free (liquid) water or condensate present?', type: 'yn' }, stm: { t: 'Steam, boiler feed water or steam condensate service?', type: 'yn' }, cw: { t: 'Cooling-water service (either side)?', type: 'yn' },
  h2s: { t: 'Does the fluid contain H2S (sour)?', type: 'yn' }, h2: { t: 'Is hydrogen present (partial pressure above about 3.5 bar)?', type: 'yn' }, chl: { t: 'Chlorides in the fluid, or outside (marine air, deluge, wet insulation)?', type: 'yn' },
  caus: { t: 'Caustic (NaOH / KOH, spent caustic) in the fluid?', type: 'yn' }, amine: { t: 'Amine service (MEA, DEA, MDEA)?', type: 'yn' }, co2: { t: 'CO2 in the fluid?', type: 'yn' }, o2: { t: 'Oxygen or oxygen-enriched gas service?', type: 'yn' },
  sulf: { t: 'Sulfur compounds in the fluid (H2S, mercaptans) at high temperature?', type: 'yn' }, nh3: { t: 'Ammonia in the fluid (anhydrous or in water)?', type: 'yn' }, hc: { t: 'Hydrocarbon service?', type: 'yn' }, lpg: { t: 'LPG / propane / butane / ethane / ethylene — can it cool the vessel when pressure is let down?', type: 'yn' },
  acid: { t: 'Acid service?', type: 'acid' }, nap: { t: 'Naphthenic acid (crude / heavy oil with acid)?', type: 'yn' }, oil: { t: 'Fired with fuel oil?', type: 'yn' },
  insul: { t: 'Insulated or fire-proofed?', type: 'yn' }, cyc: { t: 'Temperature or pressure cycling (start-stop, batch, regeneration, swing)?', type: 'yn' }, vib: { t: 'Vibration (pumps, compressors, small-bore branches)?', type: 'yn' },
  vel: { t: 'High velocity, two-phase flow, or solids (catalyst, powder, slurry) in the fluid?', type: 'yn' }, pwht: { t: 'Was it post-weld heat treated (PWHT / stress relieved)?', type: 'yn' }, soil: { t: 'Is any part buried or touching soil?', type: 'yn' },
  fired: { t: 'Fired equipment (heater / boiler tubes in flue gas)?', type: 'yn' }, dmw: { t: 'Welds between carbon / Cr-Mo steel and stainless steel?', type: 'yn' }, stag: { t: 'Low-flow or stagnant parts, dead legs, or hydrotest water left inside?', type: 'yn' }, oacid: { t: 'Organic acids (formic / acetic, from crude or additives) in condensing water?', type: 'yn' }, aer: { t: 'Oxygen / air can get into the water (aerated, open system, poor deaeration)?', type: 'yn' },
  thick: { t: 'Wall thicker than 50 mm, or plate without impact (Charpy) test?', type: 'yn' }, refr: { t: 'Refractory lined?', type: 'yn' }, galv: { t: 'Two different metals in contact (e.g. brass tubes in steel tubesheet)?', type: 'yn' },
  lmetal: { t: 'Mercury in the gas, or galvanised parts close to stainless / aluminium?', type: 'yn' }, hard: { t: 'Hard welds or high-strength steel / bolts (hardness above ~22 HRC)?', type: 'yn' }, year: { t: 'Year built', type: 'num' }
}

export const DM_ORDER: Record<DmAnswer, number> = { yes: 0, maybe: 1, "?": 2, no: 3 };

/** Screen every mechanism for one set of answers. */
export function screenAll(x: DmX) {
  const R = DM_LIB.map((d) => { let r: DmScreen; try { r = d.scr(x) || { r: "no" }; } catch { r = { r: "?", why: "", need: [] }; } return { d, r: r.r, why: r.why || "", need: r.need || [] }; })
    .sort((a, b) => DM_ORDER[a.r] - DM_ORDER[b.r] || a.d.n.localeCompare(b.d.n));
  const cnt: Record<string, number> = {};
  R.filter((r) => r.r === "?").forEach((r) => r.need.forEach((k) => (cnt[k] = (cnt[k] || 0) + 1)));
  const questions = Object.entries(cnt).sort((a, b) => b[1] - a[1]).map(([k, n]) => ({ k, n }));
  return { all: R, yes: R.filter((r) => r.r === "yes"), maybe: R.filter((r) => r.r === "maybe"), open: R.filter((r) => r.r === "?"), questions };
}

export const dmById = (id: string) => DM_LIB.find((d) => d.id === id);

/** Readable URL slug for a mechanism page, e.g. "corrosion-under-insulation-cui". */
export const dmSlug = (d: { n: string }) => d.n.toLowerCase().replace(/°/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
export const dmBySlug = (s: string) => DM_LIB.find((d) => dmSlug(d) === s);
